from pyvkteamsclient.admin.base.client import BaseAdminClient
from pyvkteamsclient.tracer import tracer


class DashboardMethods(BaseAdminClient):
    @tracer.start_as_current_span("admin.dashboard.api_dashboard")
    def api_dashboard(self):
        """
        Возвращает список файлов с описанием системы для дашборда
        """
        return self.get(path="api/dashboard")

    @tracer.start_as_current_span("admin.dashboard.api_misc_client_versions")
    def api_misc_client_versions(self):
        """
        Возвращает номер текущего релиза Myteam и версии всех клиентов
        """
        return self.get(path="api/misc/client_versions")
